/* Presentation only: never reads a session, student record or financial API. */
(()=>{'use strict';
const menu=document.querySelector('.menu-toggle'),nav=document.getElementById('academy-nav');
function closeMenu(){nav?.classList.remove('is-open');menu?.setAttribute('aria-expanded','false');menu?.setAttribute('aria-label','باز کردن فهرست');}
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'بستن فهرست':'باز کردن فهرست');nav.classList.toggle('is-open',open);});
nav?.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu();});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});document.addEventListener('click',e=>{if(!e.target.closest('.academy-header'))closeMenu();});
const tabs=[...document.querySelectorAll('[data-experience]')],panels=[...document.querySelectorAll('.experience-panel')];
const play=document.getElementById('sample-play'),status=document.getElementById('sample-status'),player=document.querySelector('.sample-player');let audio=null,playGeneration=0;
function idle(){player?.classList.remove('is-playing');if(play){play.setAttribute('aria-pressed','false');play.setAttribute('aria-label','پخش نمونه صدای ویولن');play.firstElementChild.className='play-glyph';}}
function stop(){playGeneration++;if(audio){audio.pause();audio.currentTime=0;}idle();if(status)status.textContent='برای شنیدن، دکمهٔ پخش را بزن.';}
function activate(tab,focus=false){stop();tabs.forEach(t=>{const chosen=t===tab;t.setAttribute('aria-selected',String(chosen));t.tabIndex=chosen?0:-1;});panels.forEach(p=>p.hidden=p.id!==tab.getAttribute('aria-controls'));if(focus)tab.focus();}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>activate(tab));tab.addEventListener('keydown',e=>{let index=i;if(e.key==='ArrowLeft')index=(i+1)%tabs.length;else if(e.key==='ArrowRight')index=(i-1+tabs.length)%tabs.length;else if(e.key==='Home')index=0;else if(e.key==='End')index=tabs.length-1;else return;e.preventDefault();activate(tabs[index],true);});});
play?.addEventListener('click',async()=>{if(audio&&!audio.paused){stop();return;}if(!audio){audio=new Audio('audio/guide-clips/sound-bow.mp3');audio.preload='none';audio.addEventListener('ended',()=>{idle();status.textContent='نمونه تمام شد. دوباره می‌توانی بشنوی.';});audio.addEventListener('error',()=>{idle();status.textContent='صدا دریافت نشد؛ اتصال را بررسی کن و دوباره پخش را بزن.';});}const generation=++playGeneration;status.textContent='در حال آماده‌کردن نمونه…';try{await audio.play();if(generation!==playGeneration){audio.pause();return;}player.classList.add('is-playing');play.setAttribute('aria-pressed','true');play.setAttribute('aria-label','توقف نمونه صدا');play.firstElementChild.className='pause-glyph';status.textContent='در حال پخش نمونهٔ صدای ویولن';}catch{if(generation===playGeneration){idle();status.textContent='پخش انجام نشد. برای تلاش دوباره دکمهٔ پخش را بزن.';}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});window.addEventListener('pagehide',stop);
document.querySelector('[data-open-assistant]')?.addEventListener('click',()=>{stop();document.querySelector('.ha-launcher')?.click();});document.querySelectorAll('.discover-trigger').forEach(b=>b.addEventListener('click',stop));
// Collapse only after JavaScript is ready. Searching always includes the full catalog.
const library=document.querySelector('.instrument-library'),cards=[...document.querySelectorAll('.instrument-card')];
if(library&&cards.length>8){let expanded=false;const more=document.createElement('button');more.type='button';more.className='library-more';more.setAttribute('aria-expanded','false');more.textContent='همهٔ ۲۱ ساز را ببین ←';library.querySelector('.instrument-grid').after(more);function update(){const query=library.querySelector('#instrument-search').value.trim(),family=library.querySelector('[aria-pressed="true"][data-filter]')?.dataset.filter;const filtered=!!query||!!family&&family!=='all';cards.forEach((c,i)=>c.classList.toggle('library-folded',!expanded&&!filtered&&i>=8));more.hidden=filtered;more.setAttribute('aria-expanded',String(expanded));more.textContent=expanded?'نمایش کوتاه‌تر ↑':'همهٔ ۲۱ ساز را ببین ←';}more.addEventListener('click',()=>{expanded=!expanded;update();if(!expanded)library.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});library.addEventListener('input',update);library.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>queueMicrotask(update)));update();}
const masters=document.querySelector('.masters'),teacherCards=[...document.querySelectorAll('.master')];
if(masters&&teacherCards.length>8){let expanded=false;const more=document.createElement('button');more.type='button';more.className='masters-more';more.setAttribute('aria-expanded','false');masters.querySelector('.master-grid').after(more);function update(){const query=masters.querySelector('#master-search').value.trim(),category=masters.querySelector('.selected[data-filter]')?.dataset.filter;const filtered=!!query||!!category&&category!=='all';teacherCards.forEach((c,i)=>c.classList.toggle('master-folded',!expanded&&!filtered&&i>=8));more.hidden=filtered;more.setAttribute('aria-expanded',String(expanded));more.textContent=expanded?'نمایش کوتاه‌تر ↑':'آشنایی با همهٔ استادها ←';}more.addEventListener('click',()=>{expanded=!expanded;update();if(!expanded)masters.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});masters.addEventListener('input',update);masters.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>queueMicrotask(update)));update();}
})();
